import{_ as a,o as t,c as i,a5 as s}from"./chunks/framework.BwlBv862.js";const u=JSON.parse('{"title":"範囲を絞って変更に貢献する","description":"","frontmatter":{"title":"範囲を絞って変更に貢献する","docId":"developer.contributing","translationKey":"developer.contributing","locale":"ja","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2e0522178ebee69ea5eb20fec3c0ec586f13950c51d658cb3a21843536b2f9f9","translationRevision":"58c0105316e54689625a140866a31ebc5ad44b40040d0ab0e71fd8960c240d80","order":230},"headers":[],"relativePath":"ja/developer/contributing.md","filePath":"ja/developer/contributing.md","lastUpdated":1794611623000}'),n={name:"ja/developer/contributing.md"};function r(o,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="contributing-focused-changes" tabindex="-1">範囲を絞って変更に貢献する <a class="header-anchor" href="#contributing-focused-changes" aria-label="Permalink to &quot;範囲を絞って変更に貢献する {#contributing-focused-changes}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>他の貢献者が確認・検証できる変更を準備します。編集前に <a href="https://github.com/nglmercer/TikTools-app/blob/remake/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a>、適用される <code>AGENTS.md</code>、<a href="./setup.html">セットアップ</a> を読みます。Bun 1.4.4、必要に応じ Rust 1.95 以降、コミット済みロックファイル、目的の対象から作ったブランチを使います。</p><h2 id="define-and-implement-the-change" tabindex="-1">変更を定めて実装する <a class="header-anchor" href="#define-and-implement-the-change" aria-label="Permalink to &quot;変更を定めて実装する {#define-and-implement-the-change}&quot;">​</a></h2><ol><li><code>git status</code> を確認し、他の担当者の作業を保全します。生成アセット、認証情報、ローカル DB を差分に含めません。</li><li>現在の担当箇所に従います。サービス動作は Rust コア、契約は Control API モジュール、SDK 対応は型付きクライアント、表示は<a href="./frontend.html">フロントエンド構成</a> です。</li><li>契約変更は正規の定義を更新し、派生出力も一緒に再生成します。別の完全な RPC・イベントスキーマ表を手で維持しません。</li><li>プラグイン固有実装は外部パッケージに置きます。汎用ホストは特定プラグインを取り込まず、マニフェストを検出します。</li><li>具体的なきっかけと変更後の動作を、未完了・実験的な経路も含めて説明します。</li></ol><h2 id="validate-proportionately" tabindex="-1">変更に応じて検証する <a class="header-anchor" href="#validate-proportionately" aria-label="Permalink to &quot;変更に応じて検証する {#validate-proportionately}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-lint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><p>ネイティブ実装の変更には対応する Rust の整形、lint、テストと必須 CI 条件も必要です。文書のみの変更では docs 検査とコマンド・ソースリンクの確認を行い、ネイティブ実動作の受け入れを主張しません。対応入口はプロジェクトのタスクランナーが管理し、固有の対象フラグは Cargo 引き渡しを使います。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>レビューには焦点を絞った変更、有意な検証証拠、正直な制限を含めます。方針上の PR 対象は <code>remake</code>、リリースタグは保守担当者が管理します。貢献手順は利用できますが、ブランチ保護とリモート検査設定は管理者の責任で、Markdown ページが保証するものではありません。</p><h2 id="recover" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recover" aria-label="Permalink to &quot;問題が起きたとき {#recover}&quot;">​</a></h2><p>依存関係や環境ライブラリ不足で検証が失敗したら、検査を弱めず環境を報告・修復します。生成物がずれたら所有元から再生成し差分を確認します。Cookie、鍵、認証情報、未処理のイベント記録を公開しません。ソースと古い設計が異なる場合は差を説明し、公開ガイドは現行実装に従います。広範な整理を一貫して見せるために他の担当者の未完了ファイルを上書きしないでください。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;運用の詳細 {#operational-details}&quot;">​</a></h2><p>review stamp は別々です。<code>sourceRevision</code> は現在の英語本文、<code>translationRevision</code> はこの記事の翻訳本文（frontmatter と外側空白を除去）の hash です。原文と全翻訳を確認して <code>bun docs/scripts/record-review.ts developer/example.md</code> を実行します。以後の本文編集は対応 stamp を無効にします。これは変化検出で、人間の ID・意味同等性の証明ではありません。コマンド・RPC/環境 ID・payload key・制限・有効化/回復・否定を明示比較し、技術指示を保持して全文章を訳します。</p><p>分割移行は元 topic/heading ごとに具体的な移行先を記録し、節なら fragment を付けます。checker はファイル・fragment・歴史 bytes を検証しますが、話題網羅は編集 review が必要です。成功のために歴史原文・provenance を書き換えません。</p>`,15)])])}const k=a(n,[["render",r]]);export{u as __pageData,k as default};
